@@ -47,9 +49,15 @@ nsresult nsMsgFileHdr::ReadFile() {
   rv = fileStream->Init(mFile, PR_RDONLY, 0664, 0);
   NS_ENSURE_SUCCESS(rv, rv);

+  int64_t fileSize;
