+  mozilla::Buffer<char> buffer(std::min(fileSize, 500 * 1024L));
   uint32_t count;
-  char buffer[8192];
-  rv = fileStream->Read(&buffer[0], 8192, &count);
+  rv = fileStream->Read(buffer.Elements(), buffer.Length(), &count);
   NS_ENSURE_SUCCESS(rv, rv);

